from textlesson import build
S=dict(cls=6,subj="science",subj_file="science")
build(dict(S,ch="materials-around-us",topic="sorting-materials",name_en="Sorting materials by their properties",name_ta="பொருட்களை அவற்றின் பண்புகளால் பிரித்தல்",
 objectives=["Sort materials by properties such as hardness, transparency and solubility","Choose a suitable material for a job"],
 story=("The best material for a window","Dev's school was building a new window. \"Why not use wood?\" asked a boy.\nThe teacher held a sheet of glass and a plank of wood to the light. Dev could see through the glass but not through the wood.\n\"A window must let light through,\" she said. \"So we choose glass.\""),
 explain=["Everything around us is made of materials, such as wood, glass, metal, plastic, cotton and rubber.","We group materials by their properties. Appearance can be shiny (metals) or dull. Hard materials such as iron are hard to scratch; soft ones such as cotton or sponge can be pressed easily.","Transparent materials such as clear glass let light pass so we see clearly through them. Translucent materials such as butter paper let some light pass. Opaque materials such as wood and metal let no light pass.","Some materials dissolve in water. Sugar and salt are soluble. Sand and chalk powder are insoluble. Some things float on water and some sink.","We choose a material for its properties. Cooking pans are metal because metal is hard and heats up well. Windows are glass because glass is transparent."],
 terms=["transparent","translucent","opaque","soluble","insoluble","property"],
 narr=[("Things are made of materials. We sort them by their properties, like hard or soft, shiny or dull.","hard / soft, shiny / dull"),("Clear glass is transparent. Butter paper is translucent. A wooden board is opaque.","transparent, translucent, opaque"),("Sugar and salt dissolve in water. They are soluble. Sand does not dissolve. It is insoluble.","soluble / insoluble"),("We pick a material by what we need. A pan is made of metal. A window is made of glass.","right material, right job")],
 ex=("Why is a cooking pan made of metal and its handle of plastic or wood?",[("The pan must be hard and must pass heat quickly.","Metals do both."),("The handle should not get hot in our hands.","Plastic and wood do not pass heat easily."),("So each part uses the material with the right property.","The job decides the material.")]),
 tb=("Your friend wants a window made of a wooden sheet. What will you tell her?",["A window must let light through.","Wood is opaque but glass is transparent, so glass is better."],["Thinking any hard material can be used for any job."]),
 summary=["Materials are sorted by their properties.","Transparent, translucent and opaque describe how much light passes.","Soluble things dissolve in water; insoluble ones do not.","We choose a material for its properties."],
 q=[("mcq",1,"r1-clear","Which material is transparent?","clear glass",[("a wooden board","Wood is opaque."),("a steel plate","Steel is opaque.")],"We can see clearly through clear glass."),
    ("tf",1,"r1-sugar","Sugar dissolves in water.",True,"True. Sugar is soluble."),
    ("mcq",2,"r2-opaque","What does an opaque material do to light?","lets no light pass",[("lets all light pass","That is transparent."),("lets some light pass","That is translucent.")],"Opaque things block light."),
    ("tf",2,"r2-sand","Sand dissolves in water.",False,"False. Sand is insoluble."),
    ("mcq",3,"r3-butter","Butter paper lets some light pass. It is","translucent",[("transparent","Transparent lets almost all light pass."),("opaque","Opaque lets none pass.")],"Butter paper is translucent."),
    ("short",3,"r3-soluble","Name one thing that dissolves in water.",["sugar","salt"],"Sugar and salt are soluble."),
    ("mcq",4,"r4-handle","Why is a pan handle made of plastic or wood?","they do not pass heat easily",[("they are transparent","Transparency has nothing to do with it."),("they are heavy","Weight is not the reason.")],"The handle should stay cool."),
    ("tf",4,"r4-choice","We choose a material by looking at the property that the job needs.",True,"True. A window needs glass because it is transparent.")]))
build(dict(S,ch="temperature-and-its-measurement",topic="measuring-temperature",name_en="Measuring temperature",name_ta="வெப்பநிலையை அளத்தல்",
 objectives=["Say what temperature tells us","Read a thermometer correctly and know normal body temperature"],
 story=("Is it a fever?","Meena felt hot and tired. Her mother touched her forehead and said, \"I think you have a fever, but touch can be wrong.\"\nShe placed a thermometer under Meena's tongue for a minute. It showed 38.5 degrees Celsius.\n\"Now we know for sure,\" said her mother."),
 explain=["Temperature tells us how hot or cold something is. Our sense of touch can be wrong, so we use a thermometer.","Temperature is measured in degrees Celsius (written °C). Water freezes at 0 °C and boils at 100 °C.","A laboratory thermometer has a bulb with a liquid inside a thin tube. When the bulb gets hot, the liquid rises in the tube. We read the scale at the top of the liquid.","A clinical thermometer is used for body temperature. Normal human body temperature is about 37 °C. A clinical thermometer is not used for hot water because it reads only about 35 °C to 42 °C.","Before using a clinical thermometer, shake it so that the liquid goes below 35 °C. After use, wash it and keep it safely. Hold a laboratory thermometer upright and do not let the bulb touch the glass."],
 terms=["temperature","thermometer","Celsius","clinical thermometer"],
 narr=[("Temperature tells how hot or cold something is. Touch can mislead us, so we use a thermometer.","hot or cold? use a thermometer"),("We measure temperature in degrees Celsius. Water freezes at zero and boils at one hundred.","0 °C freeze, 100 °C boil"),("A clinical thermometer is for the body. Normal body temperature is about thirty-seven degrees.","normal: 37 °C"),("Shake the clinical thermometer before use, and read the scale where the liquid ends.","shake, then read")],
 ex=("A thermometer shows 39 °C for a child. Is the child's temperature normal?",[("Normal body temperature is about 37 °C.","This is the reference value."),("39 °C is higher than 37 °C.","A higher value means the body is hotter than normal."),("So it is not normal; the child may have a fever and should see a doctor.","A temperature this high needs care.")]),
 tb=("A friend wants to measure boiling water with a clinical thermometer. What will you tell him?",["A clinical thermometer reads only about 35 to 42 degrees Celsius.","Boiling water is about 100 °C, so the thermometer could break; use a laboratory thermometer."],["Thinking all thermometers work for all temperatures."]),
 summary=["A thermometer measures temperature in °C.","Water freezes at 0 °C and boils at 100 °C.","Normal body temperature is about 37 °C.","Shake a clinical thermometer before using it."],
 q=[("mcq",1,"r1-unit","In which unit do we usually measure temperature?","degree Celsius",[("metre","Metre measures length."),("kilogram","Kilogram measures mass.")],"Temperature is measured in degrees Celsius."),
    ("tf",1,"r1-touch","Our sense of touch always tells the exact temperature.",False,"False. Touch can be wrong, so we use a thermometer."),
    ("mcq",2,"r2-normal","What is the normal human body temperature?","about 37 °C",[("about 10 °C","That is far too cold."),("about 100 °C","That is the boiling point of water.")],"Normal body temperature is about 37 °C."),
    ("tf",2,"r2-boil","Water boils at 100 °C.",True,"True."),
    ("mcq",3,"r3-shake","What should we do before using a clinical thermometer?","shake it so the liquid goes down",[("heat it","Heating it can break it."),("dip it in hot water","The clinical thermometer is not for hot water.")],"Shaking brings the liquid below 35 °C."),
    ("short",3,"r3-freeze","At what temperature in °C does water freeze?",["0","zero","0 degree","0 °c"],"Water freezes at 0 °C."),
    ("mcq",4,"r4-clinical","A clinical thermometer is used to measure","body temperature",[("boiling water","It would be damaged."),("a hot oven","It would be damaged.")],"It is meant for body temperature."),
    ("tf",4,"r4-liquid","In a thermometer the liquid rises when the bulb gets hotter.",True,"True. This is how we read higher temperatures.")]))
build(dict(S,ch="methods-of-separation-in-everyday-life",topic="separating-mixtures",name_en="Separating mixtures",name_ta="கலவைகளைப் பிரித்தல்",
 objectives=["Choose a method to separate a mixture","Explain hand-picking, winnowing, sieving, filtration and evaporation"],
 story=("Grandmother's rice","Grandmother poured rice into a big plate. \"There are tiny stones in it,\" she said.\nShe picked out the stones, then washed the rice. The water turned cloudy, and she poured it out slowly while the rice stayed in the vessel.\n\"Every mixture needs the right method,\" she told Varun."),
 explain=["A mixture has two or more things together. We separate them when one part is not wanted or when each part is useful.","Hand-picking removes stones from rice or dal. Winnowing uses wind to separate light husk from heavy grain. Sieving separates small particles from bigger ones, such as flour from husk.","Sedimentation and decantation: when a muddy water is left, heavy mud settles at the bottom (sedimentation) and the clear water is poured off (decantation). Filtration uses filter paper or a cloth to separate solid bits from a liquid.","Evaporation separates a dissolved solid from a liquid. When salty water is heated, the water becomes vapour and salt is left behind. This is how salt is made from sea water.","Many mixtures need more than one method. We choose the method by what is different about the parts: size, weight, or whether they dissolve."],
 terms=["mixture","winnowing","sieving","filtration","sedimentation","decantation","evaporation"],
 narr=[("A mixture has two or more things. We separate them using a difference between them.","mixture: separate the parts"),("Wind separates light husk from heavy grain. This is winnowing. A sieve separates small particles from big ones.","winnowing, sieving"),("Let muddy water stand. Mud settles, and we pour off the clear water. A cloth or filter paper can also remove bits.","sedimentation, decantation, filtration"),("Heat salty water. The water turns into vapour and salt is left. This is evaporation.","evaporation gives salt")],
 ex=("A bowl has salt dissolved in water. How can we get the salt back?",[("Salt is dissolved, so filtration will not work.","The salt passes through the filter with the water."),("Heat the water slowly so it evaporates.","Water becomes vapour and leaves."),("The salt is left behind in the bowl.","This is separation by evaporation.")]),
 tb=("A friend says we can separate salt from salty water with filter paper. Is he right?",["No, because salt is dissolved and passes through the filter paper.","We should evaporate the water to get the salt."],["Thinking filtration separates anything from a liquid."]),
 summary=["Mixtures are separated using a difference between the parts.","Winnowing, sieving, filtration, sedimentation and decantation separate solids.","Evaporation separates a dissolved solid from a liquid."],
 q=[("mcq",1,"r1-stones","Which method removes stones from rice?","hand-picking",[("evaporation","Evaporation is for dissolved solids."),("winnowing","Winnowing uses wind for light and heavy parts.")],"Hand-picking removes bigger unwanted pieces."),
    ("tf",1,"r1-wind","Winnowing uses wind to separate light husk from heavy grain.",True,"True."),
    ("mcq",2,"r2-sieve","Flour is passed through a sieve to","separate big bits from the fine flour",[("dissolve the flour","A sieve does not dissolve things."),("make flour heavier","A sieve does not change weight.")],"A sieve separates by size."),
    ("tf",2,"r2-filter","Filtration can separate sand from water.",True,"True. The cloth or filter paper stops the sand."),
    ("mcq",3,"r3-salt","How can we get salt from salty water?","evaporate the water",[("filter it","The salt would pass through."),("winnow it","Winnowing is for dry grain.")],"Evaporation leaves the salt behind."),
    ("short",3,"r3-settle","What do we call it when heavy mud settles at the bottom of water?",["sedimentation","settling"],"The settling of heavy bits is sedimentation."),
    ("mcq",4,"r4-decant","Pouring off the clear water without disturbing the settled mud is called","decantation",[("evaporation","Evaporation is water turning to vapour."),("sieving","Sieving uses a sieve.")],"This is decantation."),
    ("tf",4,"r4-choice","We choose the method of separation by looking at how the parts differ.",True,"True. Size, weight and dissolving decide the method.")]))
build(dict(S,ch="mindful-eating-a-path-to-a-healthy-body",topic="food-and-nutrients",name_en="Food and nutrients",name_ta="உணவும் ஊட்டச்சத்துகளும்",
 objectives=["Name the main nutrients and what each does","Plan a balanced meal"],
 story=("Lunchbox swap","Arun's lunchbox had only biscuits. Priya's had rice, dal, a vegetable and a fruit.\n\"Why do you eat so many things?\" asked Arun.\n\"My body needs different foods to grow, play and stay well,\" said Priya."),
 explain=["Food gives us energy and helps us grow and stay healthy. The useful parts of food are called nutrients.","Carbohydrates (rice, wheat, potato) give energy. Proteins (dal, eggs, milk, fish) help the body grow and repair. Fats (oil, ghee, nuts) give a lot of energy.","Vitamins and minerals (fruits, vegetables, milk) protect the body from disease. Fibre (whole grains, vegetables) helps us pass waste. Water is also needed.","A balanced diet has all nutrients in the right amounts. Eating only one kind of food, or too much junk food, is not healthy.","Mindful eating means eating slowly, chewing well, not wasting food and washing hands before eating."],
 terms=["nutrients","carbohydrates","proteins","fats","vitamins","minerals","fibre","balanced diet"],
 narr=[("Food gives energy and helps us grow. The useful parts of food are nutrients.","food: energy and growth"),("Carbohydrates and fats give energy. Proteins help us grow and repair.","carbohydrates, fats: energy; proteins: growth"),("Vitamins and minerals protect us from disease. Fibre helps digestion.","vitamins, minerals, fibre"),("A balanced diet has all the nutrients. Eat slowly, chew well and do not waste food.","balanced diet")],
 ex=("Which nutrient is missing from a meal of only rice and oil, and which foods can add it?",[("Rice gives carbohydrates and oil gives fats.","These give energy."),("Proteins, vitamins and minerals are missing.","The meal has no dal, vegetable or fruit."),("We can add dal for protein and vegetables and a fruit for vitamins and minerals.","Now the meal is more balanced.")]),
 tb=("A friend eats only chips and sweets every day. What will you tell him?",["His body needs all nutrients in the right amounts.","He should add dal, vegetables, fruit and milk and eat less junk food."],["Thinking tasty food is the same as healthy food."]),
 summary=["Nutrients are carbohydrates, proteins, fats, vitamins, minerals, fibre and water.","A balanced diet has all of them.","Eat slowly and do not waste food."],
 q=[("mcq",1,"r1-energy","Which nutrient mainly gives energy?","carbohydrates",[("fibre","Fibre helps digestion."),("water","Water helps in many ways but is not the main energy source.")],"Carbohydrates are the main energy food."),
    ("tf",1,"r1-dal","Dal gives us protein.",True,"True."),
    ("mcq",2,"r2-grow","Which nutrient helps the body grow and repair?","proteins",[("fats","Fats mainly give energy."),("minerals","Minerals protect and help the body work.")],"Proteins build and repair the body."),
    ("tf",2,"r2-junk","Eating only junk food is a balanced diet.",False,"False. A balanced diet needs many kinds of food."),
    ("mcq",3,"r3-vit","Fruits and vegetables are rich in","vitamins and minerals",[("only fats","Fruits and vegetables have little fat."),("only sugar","They have many other nutrients.")],"They protect the body from disease."),
    ("short",3,"r3-carb","Name one food rich in carbohydrates.",["rice","wheat","potato","roti","bread"],"Rice, wheat and potato are rich in carbohydrates."),
    ("mcq",4,"r4-balanced","A balanced diet has","all the nutrients in the right amounts",[("only one nutrient","That is not balanced."),("only sweet food","That is not balanced.")],"Balance means all nutrients in the right amounts."),
    ("tf",4,"r4-mindful","Chewing food well and not wasting it is part of mindful eating.",True,"True.")]))
